# Production-Ready Template Injection Defenses

## Tier 2: Essential Security Controls

### Input Validation + Security Headers + Allowlist Restrictions

```javascript
const express = require('express');
const ejs = require('ejs');
const helmet = require('helmet');
const winston = require('winston');
const validator = require('validator');

const app = express();

app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

// Security logger
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console()
  ]
});

// DEFENSE 1: Security headers with helmet
app.use(helmet());

// DEFENSE 2: Strict Content Security Policy
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"], // No inline scripts
    objectSrc: ["'none'"],
    baseUri: ["'self'"],
    formAction: ["'self'"]
  }
}));

// DEFENSE 3: Input validation middleware
const DANGEROUS_PATTERNS = [
  /<%[^>]*%>/,           // EJS syntax
  /\$\{[^}]*\}/,         // Template literals
  /{{[^}]*}}/,           // Handlebars/Mustache syntax
  /require\s*\(/,        // Node.js require
  /process\./,           // Process access
  /child_process/,       // Command execution
  /eval\s*\(/,           // Eval
  /Function\s*\(/,       // Function constructor
  /__proto__/,           // Prototype pollution
  /constructor/          // Constructor access
];

function validateInput(input) {
  if (!input || typeof input !== 'string') {
    return { valid: false, reason: 'Invalid input type' };
  }

  // Length limit
  if (input.length > 500) {
    return { valid: false, reason: 'Input too long' };
  }

  // Check for dangerous patterns
  for (const pattern of DANGEROUS_PATTERNS) {
    if (pattern.test(input)) {
      return { 
        valid: false, 
        reason: 'Suspicious pattern detected',
        pattern: pattern.toString()
      };
    }
  }

  // Allowlist approach: only allow safe characters
  const allowedChars = /^[a-zA-Z0-9\s.,!?'"\-()]+$/;
  if (!allowedChars.test(input)) {
    return { 
      valid: false, 
      reason: 'Invalid characters detected'
    };
  }

  return { valid: true };
}

// SECURE: Multiple layers of defense
app.get('/message', (req, res) => {
  const userInput = req.query.msg || 'Hello';
  const clientIp = req.ip;
  const timestamp = new Date().toISOString();

  // DEFENSE 4: Input validation
  const validation = validateInput(userInput);

  if (!validation.valid) {
    securityLogger.warn({
      event: 'template_injection_attempt_blocked',
      reason: validation.reason,
      pattern: validation.pattern,
      input: userInput.substring(0, 100), // Log first 100 chars only
      client_ip: clientIp,
      timestamp: timestamp,
      severity: 'HIGH'
    });

    return res.status(400).json({ 
      error: 'Invalid input',
      message: 'Your input contains characters or patterns that are not allowed'
    });
  }

  // DEFENSE 5: Additional sanitization
  const sanitizedMessage = validator.escape(userInput);

  // DEFENSE 6: Use static template with data separation
  try {
    res.render('message', { 
      message: sanitizedMessage,
      // Pass safe, controlled data only
      timestamp: new Date().toLocaleString()
    });

    securityLogger.info({
      event: 'message_rendered',
      client_ip: clientIp,
      message_length: sanitizedMessage.length,
      timestamp: timestamp
    });

  } catch (err) {
    securityLogger.error({
      event: 'template_render_error',
      error: err.message,
      client_ip: clientIp,
      timestamp: timestamp
    });

    res.status(500).send('An error occurred');
  }
});

app.listen(3000);
```

### Secure Template Configuration

```javascript
// DEFENSE 7: Restrict template engine capabilities
const secureEjsOptions = {
  // Disable client-side execution
  client: false,

  // Use strict mode
  strict: true,

  // Disable debug mode in production
  debug: process.env.NODE_ENV !== 'production',

  // Set custom delimiter if needed (reduces attack surface)
  delimiter: '%',

  // Disable async rendering (simpler security model)
  async: false,

  // Prevent including arbitrary files
  root: path.join(__dirname, 'views'),

  // Character encoding
  encoding: 'utf8'
};

// Apply secure options globally
app.set('view options', secureEjsOptions);
```

### Template Isolation

```javascript
// DEFENSE 8: Create isolated render context
const vm = require('vm');

function renderTemplateSecurely(templatePath, data) {
  // Read template file
  const templateContent = fs.readFileSync(templatePath, 'utf8');

  // Create sandbox context with limited capabilities
  const sandbox = {
    // Only expose safe data
    data: data,

    // No access to process, require, etc.
    console: undefined,
    process: undefined,
    require: undefined,
    global: undefined,
    module: undefined
  };

  try {
    // Compile and run in isolated context
    const compiledTemplate = ejs.compile(templateContent, secureEjsOptions);
    const result = compiledTemplate(data);
    return result;
  } catch (err) {
    securityLogger.error({
      event: 'template_compilation_error',
      template: templatePath,
      error: err.message
    });
    throw new Error('Template rendering failed');
  }
}
```

## Tier 3: Production Hardening

### Comprehensive Test Suite

```javascript
const request = require('supertest');
const { expect } = require('chai');

describe('Template Injection Prevention', () => {
  describe('EJS Syntax Blocking', () => {
    it('should escape template execution syntax', async () => {
      const response = await request(app)
        .get('/message?msg=<%= 1+1 %>');
      expect(response.status).to.equal(400);
    });

    it('should block process access attempts', async () => {
      const response = await request(app)
        .get('/message?msg=<%= process.env.SECRET %>');
      expect(response.status).to.equal(400);
    });

    it('should block require statements', async () => {
      const response = await request(app)
        .get('/message?msg=<%= require("fs") %>');
      expect(response.status).to.equal(400);
    });

    it('should block child_process execution', async () => {
      const response = await request(app)
        .get('/message?msg=<%= require("child_process").execSync("whoami") %>');
      expect(response.status).to.equal(400);
    });
  });

  describe('Alternative Template Syntax', () => {
    it('should block template literals', async () => {
      const response = await request(app)
        .get('/message?msg=${process.env.SECRET}');
      expect(response.status).to.equal(400);
    });

    it('should block Handlebars syntax', async () => {
      const response = await request(app)
        .get('/message?msg={{constructor.constructor("return process.env")()}}');
      expect(response.status).to.equal(400);
    });
  });

  describe('Code Injection Variants', () => {
    it('should block eval attempts', async () => {
      const response = await request(app)
        .get('/message?msg=<%= eval("malicious code") %>');
      expect(response.status).to.equal(400);
    });

    it('should block Function constructor', async () => {
      const response = await request(app)
        .get('/message?msg=<%= Function("return this.process.env")() %>');
      expect(response.status).to.equal(400);
    });

    it('should block prototype pollution', async () => {
      const response = await request(app)
        .get('/message?msg=<%= __proto__.polluted = true %>');
      expect(response.status).to.equal(400);
    });
  });

  describe('Safe Input Acceptance', () => {
    it('should allow alphanumeric messages', async () => {
      const response = await request(app)
        .get('/message?msg=Hello World 123');
      expect(response.status).to.equal(200);
      expect(response.text).to.include('Hello World 123');
    });

    it('should allow basic punctuation', async () => {
      const response = await request(app)
        .get('/message?msg=Hello, how are you?');
      expect(response.status).to.equal(200);
    });
  });
});
