### Real-Time Monitoring and Alerting

```javascript
const prometheus = require('prom-client');

// Metrics
const templateInjectionAttempts = new prometheus.Counter({
  name: 'template_injection_attempts_total',
  help: 'Total template injection attempts blocked',
  labelNames: ['pattern', 'client_ip']
});

const suspiciousInputDetected = new prometheus.Counter({
  name: 'suspicious_input_detected_total',
  help: 'Suspicious input patterns detected',
  labelNames: ['pattern_type']
});

const templateRenderErrors = new prometheus.Counter({
  name: 'template_render_errors_total',
  help: 'Template rendering errors',
  labelNames: ['error_type']
});

// Enhanced validation with metrics
function validateInputWithMetrics(input, clientIp) {
  const validation = validateInput(input);

  if (!validation.valid) {
    // Increment metrics
    templateInjectionAttempts.inc({ 
      pattern: validation.reason,
      client_ip: clientIp 
    });

    // Categorize pattern type
    if (input.includes('<%')) {
      suspiciousInputDetected.inc({ pattern_type: 'ejs_syntax' });
    } else if (input.includes('require(')) {
      suspiciousInputDetected.inc({ pattern_type: 'require_call' });
    } else if (input.includes('process.')) {
      suspiciousInputDetected.inc({ pattern_type: 'process_access' });
    }
  }

  return validation;
}
```

### Attack Pattern Detection and Response

```javascript
const attackThreshold = 3; // Alert after 3 suspicious requests
let attackAttempts = new Map(); // IP -> count

app.use((req, res, next) => {
  const clientIp = req.ip;
  const userInput = req.query.msg || '';

  // Check for attack patterns
  const isAttack = DANGEROUS_PATTERNS.some(pattern => pattern.test(userInput));

  if (isAttack) {
    const count = (attackAttempts.get(clientIp) || 0) + 1;
    attackAttempts.set(clientIp, count);

    if (count >= attackThreshold) {
      // Send security alert
      sendSecurityAlert({
        severity: 'CRITICAL',
        title: 'Template Injection Attack Detected',
        description: `IP ${clientIp} has made ${count} template injection attempts`,
        client_ip: clientIp,
        recent_attempts: getRecentAttempts(clientIp),
        recommended_action: 'Consider IP blocking'
      });

      // Automatically block IP temporarily (optional)
      blockIpTemporarily(clientIp, 3600); // 1 hour block

      return res.status(403).json({ 
        error: 'Access denied',
        message: 'Multiple security violations detected'
      });
    }
  }

  next();
});

// Cleanup attack tracking every hour
setInterval(() => {
  attackAttempts.clear();
}, 60 * 60 * 1000);
```

