```javascript
async function sendSecurityAlert(alert) {
  // Log detailed incident
  securityLogger.error({
    event: 'security_incident',
    ...alert,
    timestamp: new Date().toISOString()
  });

  // Send to SIEM
  await siemClient.sendEvent({
    type: 'template_injection_attack',
    severity: alert.severity,
    details: alert
  });

  // Alert security team for critical incidents
  if (alert.severity === 'CRITICAL') {
    await pagerDuty.trigger({
      routing_key: process.env.PAGERDUTY_KEY,
      event_action: 'trigger',
      payload: {
        summary: alert.title,
        severity: 'critical',
        source: 'express-template-service',
        custom_details: alert
      }
    });

    // Send Slack notification
    await slack.sendMessage({
      channel: '#security-alerts',
      text: `🚨 CRITICAL: ${alert.title}`,
      attachments: [{
        color: 'danger',
        fields: [
          { title: 'IP Address', value: alert.client_ip },
          { title: 'Attempts', value: alert.recent_attempts.length },
          { title: 'Action', value: alert.recommended_action }
        ]
      }]
    });
  }
}

function getRecentAttempts(clientIp) {
  // Query logs for recent attempts from this IP
  return securityLogger.query({
    client_ip: clientIp,
    event: 'template_injection_attempt_blocked',
    limit: 10,
    order: 'desc'
  });
}

function blockIpTemporarily(ip, durationSeconds) {
  // Add to Redis blocklist
  redisClient.setex(`blocked:${ip}`, durationSeconds, '1');

  securityLogger.warn({
    event: 'ip_blocked',
    client_ip: ip,
    duration_seconds: durationSeconds,
    reason: 'Multiple template injection attempts'
  });
}

// Middleware to check IP blocklist
app.use(async (req, res, next) => {
  const isBlocked = await redisClient.get(`blocked:${req.ip}`);
  if (isBlocked) {
    return res.status(403).json({ 
      error: 'Access denied',
      message: 'Your IP has been temporarily blocked due to suspicious activity'
    });
  }
  next();
});
```

### Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

const messageLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 50, // 50 requests per window
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  handler: (req, res) => {
    securityLogger.warn({
      event: 'rate_limit_exceeded',
      client_ip: req.ip,
      endpoint: req.path
    });
    res.status(429).json({ error: 'Rate limit exceeded' });
  }
});

app.use('/message', messageLimiter);
```

